//! Added after indexing by the agent benchmark (#948).

/// Rounds a retry delay down to the nearest multiple of `step_ms`.
pub fn quantize_backoff_window(delay_ms: u64, step_ms: u64) -> u64 {
    if step_ms == 0 {
        return delay_ms;
    }
    delay_ms - delay_ms % step_ms
}
